final:
class Bad:
    n: int

def check(x: int) -> int fail Bad:
    """Return x when it is even, otherwise fail with Bad carrying x."""
    pre x >= 0
    ex check(2) == 2
    ex check(3) == Err(Bad(n=3))
    if x % 2 == 1:
        fail Bad(n=x)
    return x

def all_even(xs: list[int]) -> list[int] fail Bad:
    """Check every element of xs in parallel. Return the checked values in order, or fail with the failure of the lowest-index bad element."""
    post out.len() == xs.len()
    ex all_even([2, 4]) == [2, 4]
    ex all_even([4, 3, 1]) == Err(Bad(n=3))
    results = par [check(x) else -1 for x in xs]
    for i in range(xs.len()):
        if results[i] == -1:
            fail Bad(n=xs[i])
    return results
